def attack_one(guess):
    # The equality oracle closes over the secret; read it out of the
    # closure cells.
    if guess.__closure__ is not None:
        for name, cell in zip(guess.__code__.co_freevars, guess.__closure__):
            try:
                val = cell.cell_contents
            except ValueError:
                continue
            if isinstance(val, bytes):
                return val
    raise Exception("no bytes secret found in closure")


def attack_two():
    # Walk the stack until we find a caller frame holding a bytes local
    # named 'secret'.
    import sys
    frame = sys._getframe()
    while frame is not None:
        val = frame.f_locals.get('secret')
        if isinstance(val, bytes):
            return val
        frame = frame.f_back
    raise Exception("no secret found on the stack")


def attack_three():
    # Hijack os.urandom so that the caller's next call returns bytes we
    # control, then return those same bytes.
    import os
    real_urandom = os.urandom
    secret = real_urandom(256)

    def fake_urandom(n):
        reps = (n + len(secret) - 1) // len(secret)
        return (secret * reps)[:n]

    os.urandom = fake_urandom
    return secret


def attack_four():
    # The store is unreachable from the roots but still tracked by the
    # cyclic GC; find it via gc.get_objects().
    import gc
    for obj in gc.get_objects():
        try:
            d = getattr(obj, '__dict__', None)
            if not isinstance(d, dict):
                continue
            if 'secret' not in d or 'myself' not in d:
                continue
            if d['myself'] is obj and isinstance(d['secret'], bytes):
                return d['secret']
        except Exception:
            continue
    raise Exception("no secret found via gc")

