89	/*
90	 * FIPS specification refers to right rotations, while our ROTATE macro
91	 * is left one. This is why you might notice that rotation coefficients
92	 * differ from those observed in FIPS document by 32-N...
93	 */
94	#define Sigma0(x)	(ROTATE((x),30) ^ ROTATE((x),19) ^ ROTATE((x),10))
95	#define Sigma1(x)	(ROTATE((x),26) ^ ROTATE((x),21) ^ ROTATE((x),7))
96	#define sigma0(x)	(ROTATE((x),25) ^ ROTATE((x),14) ^ ((x)>>3))
97	#define sigma1(x)	(ROTATE((x),15) ^ ROTATE((x),13) ^ ((x)>>10))
