102	void sha256_block_data_order (SHA256_CTX *ctx, const void *in)
103		{
104		unsigned MD32_REG_T a,b,c,d,e,f,g,h,s0,s1,T1,T2,t;
105		SHA_LONG	X[16],l,Ki;
106		int i;
107		const unsigned char *data=in;
108	
109		a = ctx->h[0];	b = ctx->h[1];	c = ctx->h[2];	d = ctx->h[3];
110		e = ctx->h[4];	f = ctx->h[5];	g = ctx->h[6];	h = ctx->h[7];
111	
112		for (i=0;i<16;i++)
113			{
114			HOST_c2l(data,l); X[i] = l;
115			Ki=K256[i];
116			T1 = l + h + Sigma1(e) + Ch(e,f,g) + Ki;
117			T2 = Sigma0(a) + Maj(a,b,c);
118			h = g;	g = f;	f = e;	e = d + T1;
119			d = c;	c = b;	b = a;	a = T1 + T2;
120			}
121	
122		for (;i<64;i++)
123			{
124			s0 = X[(i+1)&0x0f];	s0 = sigma0(s0);
125			s1 = X[(i+14)&0x0f];	s1 = sigma1(s1);
126	
127			T1 = X[i&0xf];
128			t = X[(i+9)&0xf];
129			T1 += s0 + s1 + t;
130	                X[i&0xf] = T1;
131			Ki=K256[i];
132			T1 += h + Sigma1(e) + Ch(e,f,g) + Ki;
133			T2 = Sigma0(a) + Maj(a,b,c);
134			h = g;	g = f;	f = e;	e = d + T1;
135			d = c;	c = b;	b = a;	a = T1 + T2;
136			}
137	
138		t=ctx->h[0]; ctx->h[0]=t+a;
139		t=ctx->h[1]; ctx->h[1]=t+b;
140		t=ctx->h[2]; ctx->h[2]=t+c;
141		t=ctx->h[3]; ctx->h[3]=t+d;
142		t=ctx->h[4]; ctx->h[4]=t+e;
143		t=ctx->h[5]; ctx->h[5]=t+f;
144		t=ctx->h[6]; ctx->h[6]=t+g;
145		t=ctx->h[7]; ctx->h[7]=t+h;
146		return;
147	}
