159	void SHA256_addlength(SHA256_CTX *c, size_t len) {
160		SHA_LONG l, cNl,cNh;
161		cNl=c->Nl; cNh=c->Nh;
162		l=(cNl+(((SHA_LONG)len)<<3))&0xffffffffUL;
163		if (l < cNl) /* overflow */
164		  {cNh ++;}
165	        cNh += (len>>29);
166		c->Nl=l; c->Nh=cNh;
167	}
