169	void SHA256_Update (SHA256_CTX *c, const void *data_, size_t len) {
170		const unsigned char *data=data_;
171		unsigned char *p;
172		size_t   n, fragment;
173	
174	        SHA256_addlength(c, len);
175	
176		n = c->num;
177	        p=c->data;
178		if (n != 0)	{
179	                fragment = SHA_CBLOCK-n;
180			if (len >= fragment)  {
181				memcpy (p+n,data,fragment);
182				sha256_block_data_order (c,p);
183				data  += fragment;
184				len   -= fragment;
185				memset (p,0,SHA_CBLOCK);	/* keep it zeroed */
186			}
187			else  {
188				memcpy (p+n,data,len);
189				c->num = n+(unsigned int)len;
190				return;
191			}
192		}
193	
194	        while (len >= SHA_CBLOCK) {
195			sha256_block_data_order (c,data);
196			data += SHA_CBLOCK;
197			len  -= SHA_CBLOCK;
198			}
199	
200	        c->num=len;
201		if (len != 0) {
202			memcpy (p,data,len);
203	        }
204		return;
205	}
