207	void SHA256_Final (unsigned char *md, SHA256_CTX *c)  {
208		unsigned char *p = c->data;
209		size_t n = c->num;
210		SHA_LONG cNl,cNh;
211	
212		p[n] = 0x80; /* there is always room for one */
213		n++;
214	
215		if (n > (SHA_CBLOCK-8))
216			{
217			memset (p+n,0,SHA_CBLOCK-n);
218			n=0;
219			sha256_block_data_order (c,p);
220			}
221		memset (p+n,0,SHA_CBLOCK-8-n);
222	
223		p += SHA_CBLOCK-8;
224		cNh=c->Nh; (void)HOST_l2c(cNh,p);
225		cNl=c->Nl; (void)HOST_l2c(cNl,p);
226		p -= SHA_CBLOCK;
227		sha256_block_data_order (c,p);
228		c->num=0;
229		memset (p,0,SHA_CBLOCK);
230	        {unsigned long ll;
231	         unsigned int  xn;
232			for (xn=0;xn<SHA256_DIGEST_LENGTH/4;xn++)	
233			{   ll=(c)->h[xn]; HOST_l2c(ll,md);   }
234	 	 }
235		return;
236	}
